#!/usr/bin/env python3
"""Deterministic RGB disturbances for regression-testing the quality gates.

The repository already had one clean synthetic fixture. Clean signals are the
easy case; the gates exist for the *hard* ones. This script writes small,
fully reproducible RGB traces that each isolate one documented failure mode so a
gate can be shown to reject it:

| fixture                     | what it contains                                  |
|-----------------------------|---------------------------------------------------|
| ``clean_72bpm``             | baseline: one 1.2 Hz pulse, three ROIs            |
| ``second_pulse_competing``  | 1.2 Hz pulse plus a 1.6 Hz component of equal size |
| ``no_pulse_noise``          | noise only, no cardiac component                  |
| ``clipped_channels``        | pulse rides on a saturated channel (255)          |
| ``flat_channel``            | green channel constant (no photometric variation) |
| ``illumination_step``       | pulse plus a large mid-window brightness step     |
| ``motion_burst``            | pulse plus a 3 s broadband excursion              |
| ``missing_roi_samples``     | left cheek absent for part of the window          |

Every trace is generated by :func:`build` with fixed parameters and a fixed
NumPy seed, so the files are byte-reproducible and the expected conclusions can
be asserted in both Python and TypeScript tests.

These are SOFTWARE fixtures. They exercise gates, not physiology: a synthetic
trace cannot establish accuracy on real skin, lighting or motion, and nothing
here may be quoted as a measurement result.

Usage:
    python tests/fixtures/generate_rppg_disturbance_fixtures.py
"""
from __future__ import annotations

import csv
import json
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
FS = 30.0
SECONDS = 20.0
SEED = 20261125
PULSE_HZ = 1.2  # 72 BPM
ROIS = ("forehead", "left_cheek", "right_cheek")


def _time():
    return np.arange(int(FS * SECONDS)) / FS


def _cardiac(t, amplitude_green=0.35, amplitude_red=0.45):
    """A plausible photoplethysmographic shape (fundamental + weak harmonic)."""
    fund = np.sin(2 * np.pi * PULSE_HZ * t)
    harm = 0.18 * np.sin(4 * np.pi * PULSE_HZ * t + 0.7)
    return {
        "red": amplitude_red * (fund + harm),
        "green": -amplitude_green * (fund + harm),  # green inverts vs red
        "blue": 0.05 * (fund + harm),
    }


def build(name: str) -> dict[str, np.ndarray]:
    """Return {column_name: values} for one disturbance fixture."""
    t = _time()
    rng = np.random.default_rng(SEED)
    noise = lambda scale: rng.normal(0.0, scale, t.size)  # noqa: E731
    pulse = _cardiac(t)

    columns: dict[str, np.ndarray] = {"timestamp_s": t}

    for roi_index, roi in enumerate(ROIS):
        base = {"red": 100.0 + 0.8 * roi_index, "green": 120.0 - 0.6 * roi_index,
                "blue": 90.0 + 0.4 * roi_index}
        r = base["red"] + pulse["red"] + noise(0.05)
        g = base["green"] + pulse["green"] + noise(0.05)
        b = base["blue"] + pulse["blue"] + noise(0.02)

        if name == "second_pulse_competing":
            # equal-strength competing component 0.4 Hz away from the pulse
            rival = 0.35 * np.sin(2 * np.pi * (PULSE_HZ + 0.4) * t)
            g = base["green"] + 0.35 * np.sin(2 * np.pi * PULSE_HZ * t) + rival + noise(0.05)
        elif name == "no_pulse_noise":
            r = base["red"] + noise(1.5)
            g = base["green"] + noise(1.5)
            b = base["blue"] + noise(1.0)
        elif name == "clipped_channels":
            # pulse on top of a saturated sensor channel: most samples pinned
            g = np.clip(120.0 + 200.0 + pulse["green"], 0, 255)
            r = np.clip(base["red"] + 120.0 + pulse["red"], 0, 255)
        elif name == "flat_channel":
            g = np.full(t.size, base["green"])  # no photometric variation at all
        elif name == "illumination_step":
            step = np.where(t >= SECONDS / 2, 22.0, 0.0)  # large brightness jump
            g = base["green"] + pulse["green"] + step + noise(0.05)
            r = base["red"] + pulse["red"] + 0.9 * step + noise(0.05)
        elif name == "motion_burst":
            burst = np.where((t >= 8.0) & (t <= 11.0), 12.0 * np.sin(2 * np.pi * 2.7 * t), 0.0)
            g = base["green"] + pulse["green"] + burst + noise(0.05)
            r = base["red"] + pulse["red"] + burst + noise(0.05)
        elif name == "missing_roi_samples":
            if roi == "left_cheek":
                absent = (t >= 5.0) & (t <= 12.0)
                r = np.where(absent, np.nan, r)
                g = np.where(absent, np.nan, g)
                b = np.where(absent, np.nan, b)

        columns[f"{roi}_r"] = np.round(r, 6)
        columns[f"{roi}_g"] = np.round(g, 6)
        columns[f"{roi}_b"] = np.round(b, 6)

    return columns


FIXTURES = (
    "clean_72bpm",
    "second_pulse_competing",
    "no_pulse_noise",
    "clipped_channels",
    "flat_channel",
    "illumination_step",
    "motion_burst",
    "missing_roi_samples",
)

DESCRIPTIONS = {
    "clean_72bpm": "baseline single 1.2 Hz pulse in three ROIs; expected to pass gates",
    "second_pulse_competing": "equal competing component 0.4 Hz from the pulse; peak separation must fail",
    "no_pulse_noise": "broadband noise, no cardiac component; concentration must fail",
    "clipped_channels": "saturated red/green channels; clipping check must fail",
    "flat_channel": "constant green channel; dynamic-range check must fail",
    "illumination_step": "22-count brightness step mid-window; must not be reported as a clean measurement",
    "motion_burst": "3 s 2.7 Hz excursion; motion/noise handling must reject or flag",
    "missing_roi_samples": "left cheek absent 5-12 s; per-ROI coverage must reflect it",
}


def write_all() -> list[Path]:
    written: list[Path] = []
    for name in FIXTURES:
        columns = build(name)
        path = HERE / f"rppg_disturbance_{name}.csv"
        with path.open("w", newline="", encoding="utf-8") as handle:
            writer = csv.writer(handle)
            writer.writerow(list(columns))
            for row in zip(*columns.values()):
                writer.writerow([f"{value:.8f}" if np.isfinite(value) else ""
                                 for value in row])
        written.append(path)
    return written


def main() -> int:
    written = write_all()
    manifest = {
        "note": ("Deterministic software fixtures for quality-gate regression tests. "
                 "Synthetic RGB only: these are NOT physiological recordings and cannot "
                 "support any accuracy claim."),
        "generated_by": "tests/fixtures/generate_rppg_disturbance_fixtures.py",
        "sampling_rate_hz": FS,
        "seconds": SECONDS,
        "pulse_hz": PULSE_HZ,
        "seed": SEED,
        "rois": list(ROIS),
        "fixtures": {name: {"file": f"rppg_disturbance_{name}.csv",
                            "description": DESCRIPTIONS[name]}
                     for name in FIXTURES},
    }
    (HERE / "rppg_disturbance_manifest.json").write_text(
        json.dumps(manifest, indent=1) + "\n", encoding="utf-8")
    for path in written:
        print(f"wrote {path.relative_to(HERE.parent.parent)}")
    print("wrote tests/fixtures/rppg_disturbance_manifest.json")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
